                    card.setClickable(True); card.setFocusable(True)
                    card.setPadding(AndroidUtilities.dp(14), AndroidUtilities.dp(9), AndroidUtilities.dp(14), AndroidUtilities.dp(8))
                    card.setBackground(self._ripple_bg(self._create_round_rect(bg, radius_dp=16), accent))
