        pbg.setCornerRadius(AndroidUtilities.dp(12))
        pbg.setColor(Theme.getColor(Theme.key_dialogBackground))
        pchip.setBackground(pbg)
        pchip.setPadding(AndroidUtilities.dp(10), AndroidUtilities.dp(5), AndroidUtilities.dp(10), AndroidUtilities.dp(5))
        plp = LinearLayout.LayoutParams(-2, -2)
        plp.topMargin = AndroidUtilities.dp(8)
        card.addView(pchip, plp)

        gid = 0
